import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Patient {
    String name;
    Patient(String name) { this.name = name; }
}

class Doctor {
    void treat(Patient patient) {
        System.out.println("Treating " + patient.name);
    }
}

class Professor {
    String name;
    Professor(String name) { this.name = name; }
}

class Department {
    List<Professor> professors;
    Department(List<Professor> professors) { this.professors = professors; }
}

class Order {
    private final List<OrderItem> items = new ArrayList<>();
    void addItem(String name) { items.add(new OrderItem(name)); }
}

class OrderItem {
    String name;
    OrderItem(String name) { this.name = name; }
}

public class Main {
    public static void main(String[] args) {
        Doctor doctor = new Doctor();
        Patient patient = new Patient("Asha");
        doctor.treat(patient);

        Professor professor = new Professor("Ravi");
        Department department = new Department(Arrays.asList(professor));
        System.out.println(department.professors.get(0).name);

        Order order = new Order();
        order.addItem("Book");
        System.out.println("Order item added");
    }
}

class Employee {
    String name;
    int age;

    Employee(String name, int age) {
        this.name = name;
        this.age = age;
    }

    void display() {
        System.out.println(name + " - " + age);
    }
}

public class Main {
    public static void main(String[] args) {
        Employee employee = new Employee("Neha", 28);
        employee.display();
    }
}

interface NotificationSender {
    void send(String message);
}

class EmailSender implements NotificationSender {
    public void send(String message) {
        System.out.println("Email: " + message);
    }
}

class SmsSender implements NotificationSender {
    public void send(String message) {
        System.out.println("SMS: " + message);
    }
}

public class Main {
    public static void main(String[] args) {
        NotificationSender sender = new EmailSender();
        sender.send("Interview reminder");

        sender = new SmsSender();
        sender.send("Interview reminder");
    }
}

